D=/scratch/jjyeung/orch_cd/leg_s1_local_admission; timeout 90 find $D -maxdepth 9 -type f \( -name '*.json' -o -name '*.jsonl' \) -printf '%s %p\n' 2>/dev/null | awk -v d="$D/" '{sub(d,"",$2); split($2,a,"/"); s[a[1]]+=$1; n[a[1]]++; t+=$1; if($1>2e8) big[$2]=$1} END{for(k in s) printf "%.2f GB %d files %s\n", s[k]/1e9, n[k], k; printf "TOTAL %.2f GB\n", t/1e9; for(k in big) printf "  big %.2f GB %s\n", big[k]/1e9, k}' | sort -rn | head -n 30